set -eu
python3 - <<'PY'
import json,subprocess
def cmd(argv,timeout=25):
 p=subprocess.run(argv,capture_output=True,text=True,timeout=timeout)
 return {"exit":p.returncode,"stdout":p.stdout[:7000],"stderr":p.stderr[-200:]}
root='/home/admin1/projects/debug-ai/.worktrees/debugai-pr112-gates-20261016'
head=cmd(['git','-C',root,'rev-parse','HEAD'])
status=cmd(['git','-C',root,'status','--porcelain','--untracked-files=normal'])
node=r"""
(async()=>{
 const result={mode:process.env.DEBUG_AI_CORE_GATE_DISPATCH_MODE||'NOT_DEFINED', gate_urls:{},has_key:!!process.env.AI_CORE_API_KEY,models:{}};
 const ports={granite:18181,qwen3:18182,ministral:18183,coder:18184};
 for(const [n,p] of Object.entries(ports)){
  result.gate_urls[n]=process.env['DEBUG_AI_CORE_GATE_'+n.toUpperCase()+'_URL']||'NOT_DEFINED';
  try{
   const r=await fetch('http://127.0.0.1:'+p+'/v1/models',{headers:{authorization:'Bearer '+(process.env.AI_CORE_API_KEY||'')},signal:AbortSignal.timeout(3500)});
   const v=await r.json().catch(()=>({}));
   result.models[n]={status:r.status,ids:Array.isArray(v.data)?v.data.map(x=>x.id).filter(x=>typeof x==='string').slice(0,4):[]};
  }catch(e){result.models[n]={error:e.name||'UNKNOWN'};}
 }
 console.log(JSON.stringify(result));
})().catch(e=>{console.error(e.name);process.exit(1)})
"""
p=cmd(['docker','exec','debug-ai-debug-ai-1','node','-e',node],timeout=28)
if p['exit']: raise SystemExit('DOCKER_NODE_GATE_PROBE_FAILED:'+p['stderr'])
d=json.loads(p['stdout'])
image=cmd(['docker','inspect','--format','{{.Image}}|{{index .Config.Labels "com.docker.compose.project"}}','debug-ai-debug-ai-1'])
out={'host_source_worktree_head':head['stdout'].strip() if head['exit']==0 else 'UNAVAILABLE','source_worktree_clean':status['exit']==0 and not status['stdout'].strip(),'live_container_image_project':image['stdout'].strip() if image['exit']==0 else 'UNAVAILABLE','debugai_gate_client':d,'note':'This is authenticated GET /v1/models, not real inference or six-role product success'}
body='DEBUGAI_CURRENT_HOST_GATE_PREFLIGHT\n'+json.dumps(out,ensure_ascii=False,indent=2)
r=cmd(['gh','api','-X','POST','repos/seigo-gace/debug-ai/issues/41/comments','-f','body='+body],timeout=30)
if r['exit']: raise SystemExit('GH_REPORT_FAILED:'+r['stderr'])
x=json.loads(r['stdout'])
print('HOST_GATE_PREFLIGHT_COMMENT='+x['html_url'])
PY
